// Reports (page 11). Every file is generated by the API from its own payloads and result files;
// the page only asks for it and saves it. Scenario report: every role. Evaluation and model
// reports: ANALYST and ADMIN, refused by the API (409, shown here) when the stored results are
// outdated. Audit log CSV: ADMIN only. Each export is logged in the audit log.
import { useMutation, useQuery } from '@tanstack/react-query'
import { motion } from 'framer-motion'
import { AlertTriangle, BarChart3, BrainCircuit, FileSpreadsheet, FileText, ScrollText } from 'lucide-react'
import { useState, type ReactNode } from 'react'
import { useScenario } from '../api/hooks'
import type { ReportStatus } from '../api/types'
import { DataBadge, SignalBadge } from '../components/ui/Badges'
import { Button } from '../components/ui/Button'
import { Panel, PanelTitle } from '../components/ui/Panel'
import { api, apiDownload, ApiError } from '../lib/api'
import { fadeUp, staggerContainer } from '../lib/motion'
import { useCan } from '../lib/permissions'
import { fmt } from '../lib/time'
import { useSim } from '../store/sim'
import { toast } from '../store/toast'

function useDownload() {
  return useMutation({
    mutationFn: ({ path, name }: { path: string; name: string }) => apiDownload(path, name),
    onSuccess: (name) => toast({ tone: 'success', title: 'Report saved', description: `${name} (generated by the API; logged in the audit log)` }),
    onError: (e) => toast({ tone: 'warning', title: 'Export refused', description: e instanceof ApiError ? e.message : 'Request failed' }),
  })
}

function Card({ icon, title, who, children }: { icon: ReactNode; title: string; who: string; children: ReactNode }) {
  return (
    <Panel>
      <PanelTitle hint={who}><span className="inline-flex items-center gap-2">{icon}{title}</span></PanelTitle>
      <div className="space-y-3 text-sm text-ink-muted">{children}</div>
    </Panel>
  )
}

function Stale({ s }: { s: ReportStatus['evaluation'] }) {
  if (s.status === 'ok') return <SignalBadge tone="success">result files verified</SignalBadge>
  return (
    <div role="alert" className="rounded-xl border border-signal-amber/40 bg-signal-amber/10 p-3 text-ink">
      <p className="flex items-center gap-2 font-semibold"><AlertTriangle className="h-4 w-4 text-signal-amber" aria-hidden />
        {s.status === 'missing' ? 'Missing' : 'Outdated'} - rerun <code className="font-mono">{s.command}</code> from backend/</p>
      <ul className="mt-1 list-disc pl-5 text-xs text-ink-muted">{s.reasons.map((r) => <li key={r}>{r}</li>)}</ul>
    </div>
  )
}

export function Reports() {
  const minute = useSim((s) => s.minute)
  const at = fmt(minute)
  const scenario = useScenario()
  const status = useQuery({ queryKey: ['reports-status'], queryFn: () => api<ReportStatus>('/api/reports'), retry: false, staleTime: 30_000 })
  const reports = useCan('reports')
  const admin = useCan('admin')
  const dl = useDownload()
  const [auditAction, setAuditAction] = useState('')
  const busy = (path: string) => dl.isPending && dl.variables?.path.startsWith(path)
  const s = status.data
  const ver = scenario.data?.scenario_version

  return (
    <motion.div className="mx-auto max-w-6xl space-y-6" variants={staggerContainer()} initial="hidden" animate="show">
      <motion.div variants={fadeUp}>
        <p className="text-sm uppercase tracking-[0.2em] text-signal-cyan">Reports</p>
        <h1 className="text-3xl font-bold xl:text-4xl">Export what the system computed</h1>
        <p className="mt-2 max-w-3xl text-ink-muted">
          Each file is generated by the API from the same payloads and result files the pages show; nothing is typed by hand.
          Every PDF page carries its data label in the footer.
        </p>
      </motion.div>

      <div className="grid gap-6 lg:grid-cols-2">
        <Card icon={<FileText className="h-5 w-5 text-signal-cyan" aria-hidden />} title="Scenario report" who="every role">
          <p>
            The current scenario at the clock: label, version, sim time, who generated it and when; events, conflicts and the alert
            history; every recommendation with its full explanation; decisions with who accepted or rejected them; per-train
            delays and key figures; the time-distance chart.
          </p>
          <div className="flex flex-wrap items-center gap-2 text-ink">
            <DataBadge label={scenario.data?.data_label} />
            <span className="font-mono text-xs">version {ver ?? '-'} · clock {at}</span>
          </div>
          <div className="flex flex-wrap gap-2">
            <Button size="sm" variant="primary" icon={<FileText className="h-4 w-4" aria-hidden />} loading={busy('/api/reports/scenario.pdf')}
              onClick={() => dl.mutate({ path: `/api/reports/scenario.pdf?at=${at}`, name: 'railopt_scenario.pdf' })}>PDF at {at}</Button>
            <Button size="sm" icon={<FileSpreadsheet className="h-4 w-4" aria-hidden />} loading={busy('/api/reports/scenario.csv')}
              onClick={() => dl.mutate({ path: `/api/reports/scenario.csv?at=${at}`, name: 'railopt_scenario.csv' })}>CSV at {at}</Button>
          </div>
          <p className="text-xs text-ink-dim">Move the clock on the console or the alerts page to report another time.</p>
        </Card>

        <Card icon={<BarChart3 className="h-5 w-5 text-signal-cyan" aria-hidden />} title="Evaluation report" who="analyst, admin">
          <p>
            From eval_summary.json: the methods table with 95% CIs, wins / ties / losses, the two charts, the ML-variants table
            and its generated conclusion, and the limits box. SIMULATED.
          </p>
          {s && <Stale s={s.evaluation} />}
          <Button size="sm" variant="primary" icon={<FileText className="h-4 w-4" aria-hidden />} lockedReason={reports.reason}
            disabled={s?.evaluation.status !== 'ok'} loading={busy('/api/reports/evaluation.pdf')}
            onClick={() => dl.mutate({ path: '/api/reports/evaluation.pdf', name: 'railopt_evaluation_report.pdf' })}>Evaluation PDF</Button>
        </Card>

        <Card icon={<BrainCircuit className="h-5 w-5 text-signal-cyan" aria-hidden />} title="Model report" who="analyst, admin">
          <p>
            The synthetic model card (SIMULATED training data) and the real-data model card (REAL recorded running times), each
            reproduced as generated from its JSON; the footer label changes with the part.
          </p>
          {s && <Stale s={s.model} />}
          <Button size="sm" variant="primary" icon={<FileText className="h-4 w-4" aria-hidden />} lockedReason={reports.reason}
            disabled={s?.model.status !== 'ok'} loading={busy('/api/reports/model.pdf')}
            onClick={() => dl.mutate({ path: '/api/reports/model.pdf', name: 'railopt_model_report.pdf' })}>Model PDF</Button>
        </Card>

        <Card icon={<ScrollText className="h-5 w-5 text-signal-cyan" aria-hidden />} title="Audit log" who="admin only">
          <p>Every sign-in, event, decision, acknowledgement, user change, network edit and export, with user, time and IP.</p>
          <label className="flex flex-col gap-1 text-xs text-ink-dim">Only this action (optional)
            <input value={auditAction} onChange={(e) => setAuditAction(e.target.value.toUpperCase())} placeholder="e.g. DECISION"
              className="h-10 rounded-lg border border-line/20 bg-canvas-1 px-3 font-mono text-sm text-ink" disabled={!admin.ok} />
          </label>
          <Button size="sm" variant="primary" icon={<FileSpreadsheet className="h-4 w-4" aria-hidden />} lockedReason={admin.reason}
            loading={busy('/api/admin/audit.csv')}
            onClick={() => dl.mutate({ path: `/api/admin/audit.csv${auditAction ? `?action=${encodeURIComponent(auditAction)}` : ''}`, name: 'railopt_audit_log.csv' })}>
            Audit log CSV
          </Button>
        </Card>
      </div>
    </motion.div>
  )
}
